const getParents = (parents, objs = false) => {
  if (!parents) return [];

  let finalParents = [];

  if (objs) {
    // console.log(parents);
    parents.forEach((parent) => {
      // console.log(parent);
      if (parent.id.includes(' & ')) {
        const allParents = [parents.split(' & ')];
        for (const par in allParents) {
          finalParents.push({
            id: par,
            level: parent.level,
            parent: parent.parents,
          });
        }
      } else {
        finalParents.push(parent);
      }
    });
  } else {
    parents.forEach((parent) => {
      if (parent.includes('&')) {
        finalParents.push(...parent.split(' & '));
      } else {
        finalParents.push(parent);
      }
    });
  }

  return finalParents;
};

const constructTangleLayout = (levels, options = {}) => {
  // precompute level depth
  levels.forEach((l, i) => l.forEach((n) => (n.level = i)));

  var nodes = levels.reduce((a, x) => a.concat(x), []);
  var nodes_index = {};
  nodes.forEach((d) => (nodes_index[d.id] = d));

  // objectification
  nodes.forEach((d) => {
    const parents = getParents(d.parents);
    d.parents = (parents === undefined ? [] : parents).map(
      (p) => nodes_index[p],
    );
  });

  // precompute bundles
  levels.forEach((l, i) => {
    var index = {};
    l.forEach((n) => {
      // console.log(n);
      const parents = getParents(n.parents, true);
      if (parents.length == 0) {
        return;
      }

      var id = parents
        .map((d) => d.id)
        .sort()
        .join('-X-');
      if (id in index) {
        index[id].parents = index[id].parents.concat(parents);
      } else {
        index[id] = {
          id: id,
          parents: parents.slice(),
          level: i,
          span: i - min(parents, (p) => p.level),
        };
      }
      n.bundle = index[id];
    });
    l.bundles = Object.keys(index).map((k) => index[k]);
    l.bundles.forEach((b, i) => (b.i = i));
  });

  var links = [];
  nodes.forEach((d) => {
    getParents(d.parents, true).forEach((p) =>
      links.push({ source: d, bundle: d.bundle, target: p }),
    );
  });

  var bundles = levels.reduce((a, x) => a.concat(x.bundles), []);

  // reverse pointer from parent to bundles
  bundles.forEach((b) =>
    getParents(b.parents, true).forEach((p) => {
      if (p.bundles_index === undefined) {
        p.bundles_index = {};
      }
      if (!(b.id in p.bundles_index)) {
        p.bundles_index[b.id] = [];
      }
      p.bundles_index[b.id].push(b);
    }),
  );

  nodes.forEach((n) => {
    if (n.bundles_index !== undefined) {
      n.bundles = Object.keys(n.bundles_index).map((k) => n.bundles_index[k]);
    } else {
      n.bundles_index = {};
      n.bundles = [];
    }
    n.bundles.sort((a, b) =>
      descending(
        max(a, (d) => d.span),
        max(b, (d) => d.span),
      ),
    );
    n.bundles.forEach((b, i) => (b.i = i));
  });

  links.forEach((l) => {
    if (l.bundle.links === undefined) {
      l.bundle.links = [];
    }
    l.bundle.links.push(l);
  });

  // layout
  const padding = 8;
  const node_height = 22;
  const node_width = 70;
  const bundle_width = 14;
  const level_y_padding = 16;
  const metro_d = 4;
  const min_family_height = 22;

  options.c ||= 16;
  const c = options.c;
  options.bigc ||= node_width + c;

  nodes.forEach(
    (n) => (n.height = (Math.max(1, n.bundles.length) - 1) * metro_d),
  );

  var x_offset = padding;
  var y_offset = padding;
  levels.forEach((l) => {
    x_offset += l.bundles.length * bundle_width;
    y_offset += level_y_padding;
    l.forEach((n) => {
      n.x = n.level * node_width + x_offset;
      n.y = node_height + y_offset + n.height / 2;

      y_offset += node_height + n.height;
    });
  });

  var i = 0;
  levels.forEach((l) => {
    l.bundles.forEach((b) => {
      b.x =
        max(getParents(b.parents, true), (d) => d.x) +
        node_width +
        (l.bundles.length - 1 - b.i) * bundle_width;
      b.y = i * node_height;
    });
    i += l.length;
  });

  links.forEach((l) => {
    l.xt = l.target.x;
    l.yt =
      l.target.y +
      l.target.bundles_index[l.bundle.id].i * metro_d -
      (l.target.bundles.length * metro_d) / 2 +
      metro_d / 2;
    l.xb = l.bundle.x;
    l.yb = l.bundle.y;
    l.xs = l.source.x;
    l.ys = l.source.y;
  });

  // compress vertical space
  var y_negative_offset = 0;
  levels.forEach((l) => {
    y_negative_offset +=
      -min_family_height +
        min(l.bundles, (b) =>
          min(b.links, (link) => link.ys - 2 * c - (link.yt + c)),
        ) || 0;
    l.forEach((n) => (n.y -= y_negative_offset));
  });

  // very ugly, I know
  links.forEach((l) => {
    l.yt =
      l.target.y +
      l.target.bundles_index[l.bundle.id].i * metro_d -
      (l.target.bundles.length * metro_d) / 2 +
      metro_d / 2;
    l.ys = l.source.y;
    l.c1 =
      l.source.level - l.target.level > 1
        ? Math.min(options.bigc, l.xb - l.xt, l.yb - l.yt) - c
        : c;
    l.c2 = c;
  });

  var layout = {
    width: max(nodes, (n) => n.x) + node_width + 2 * padding,
    height: max(nodes, (n) => n.y) + node_height / 2 + 2 * padding,
    node_height,
    node_width,
    bundle_width,
    level_y_padding,
    metro_d,
  };

  return { levels, nodes, nodes_index, links, bundles, layout };
};

const hasIntersection = (...arrs) => {
  let arrJoin = [];
  for (const arr of arrs) {
    if (arr) arrJoin = arrJoin.concat(arr);
  }
  const arrJoinSet = new Set(arrJoin);
  return arrJoin.length != arrJoinSet.size;
};

const Faith = () => {
  const [selected, setSelected] = useState([]);
  const [highlighted, setHighlighted] = useState([]);
  const [tangleLayout, setTangleLayout] = useState(undefined);
  const [options, setOptions] = useState({});

  useEffect(() => {
    const options = {};
    options.color ||= (d, i) => color(i);
    setTangleLayout(constructTangleLayout(_.cloneDeep(data), options));
    setOptions(options);
  }, []);

  const getFontColor = (nodeId) => {
    if (selected.includes(nodeId)) return 'red';
    if (highlighted.includes(nodeId)) return 'green';
    return 'black';
  };

  const getChildren = (newSelected) => {
    const children = [];

    for (let i = 1; i < data.length; i++) {
      for (let j = 0; j < data[i].length; j++) {
        const dataPoint = data[i][j];
        if (hasIntersection(dataPoint.parents, newSelected, children)) {
          children.push(dataPoint.id);
        } else if (dataPoint.parents?.some((p) => p.includes('&'))) {
          // Need to account for when some parents have &, we should only check one group of parents at once
          const fullParents = [];
          dataPoint.parents.forEach((p) => fullParents.push(...p.split(' & ')));
          const fullParentsAreContained =
            _.difference(fullParents, [...newSelected, ...children]).length ===
            0;
          if (fullParentsAreContained) children.push(dataPoint.id);
        }
      }
    }

    return children;
  };

  const clickNode = (nodeId) => {
    let newSelected = selected;
    if (selected.includes(nodeId)) newSelected = _.without(selected, nodeId);
    else {
      newSelected = [...selected, nodeId];
    }

    setHighlighted(getChildren(newSelected));

    setSelected(newSelected);
  };

  // console.log(selected);
  if (tangleLayout)
    return (
      <PlaygroundWrapper postTitle='faith'>
        <svg
          width={tangleLayout.layout.width}
          height={tangleLayout.layout.height}
          style={{ backgroundColor: background_color }}
        >
          {tangleLayout.bundles.map((b, i) => {
            let d = b.links
              .map(
                (l) => `
            M${l.xt} ${l.yt}
            L${l.xb - l.c1} ${l.yt}
            A${l.c1} ${l.c1} 90 0 1 ${l.xb} ${l.yt + l.c1}
            L${l.xb} ${l.ys - l.c2}
            A${l.c2} ${l.c2} 90 0 0 ${l.xb + l.c2} ${l.ys}
            L${l.xs} ${l.ys}`,
              )
              .join('');
            return (
              <>
                <path
                  className='link'
                  d={d}
                  stroke={background_color}
                  strokeWidth='5'
                  style={{ fill: 'none' }}
                />
                <path
                  className='link'
                  d={d}
                  stroke={options.color(b, i)}
                  strokeWidth='2'
                  style={{ fill: 'none' }}
                />
              </>
            );
          })}
          $
          {tangleLayout.nodes.map((n, i) => (
            <>
              <path
                className='selectable node'
                data-id={n.id}
                stroke='black'
                strokeWidth='8'
                d={`M${n.x} ${n.y - n.height / 2} L${n.x} ${
                  n.y + n.height / 2
                }`}
              />
              <path
                className='node'
                stroke='white'
                strokeWidth='4'
                d={`M${n.x} ${n.y - n.height / 2} L${n.x} ${
                  n.y + n.height / 2
                }`}
                // stroke-linecap: round is set in the css file
              />
              <text
                className='selectable'
                data-id={n.id}
                x={n.x + 4}
                y={n.y - n.height / 2 - 4}
                stroke={background_color}
                strokeWidth='2'
                style={{ fontSize: 10 }}
              >
                ${n.id}
              </text>
              <text
                x={n.x + 4}
                y={n.y - n.height / 2 - 4}
                style={{
                  fontSize: 10,
                  cursor: 'pointer',
                  fill: getFontColor(n.id),
                }}
                onClick={() => i < data[0].length && clickNode(n.id)}
              >
                {n.id}
              </text>
            </>
          ))}
        </svg>
      </PlaygroundWrapper>
    );
};

export default Faith;
